{
  "status": "SUPPORTED",
  "task_summary": "Find fastening parts and tools, perform fastening at a specific spot, and put the tool back on the bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location or assembly point where the fastening must occur.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["workbench surface", "assembly point"],
      "required_properties": ["has marked location", "receives fastener"]
      }
    ,
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "The physical part needed to secure the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["screw", "bolt", "nut", "block"],
      "required_properties": ["fits fastening target"]
      }
    ,
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "The device used to apply the fastening force.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
      "candidate_categories": ["wrench", "screwdriver", "drill"],
      "required_properties": ["can fasten", "reusable"]
      }
    ,
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The destination area where the tool is left after use.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["tabletop", "desk surface"],
      "required_properties": ["flat", "stable", "accessible"]
      }
    ],
    "functional_relations": [
      {
        "id": "component_suitability",
        "relation": "suitable_for",
        "participant_roles": ["compatible_component", "fastening_target"],
        "required": true
      }
    ,
      {
        "id": "tool_effectiveness",
        "relation": "effective_on",
        "participant_roles": ["fastening_tool", "fastening_target"],
        "required": true
      }
    ,
      {
        "id": "tool_placement",
        "relation": "placed_on",
        "participant_roles": ["fastening_tool", "workbench_surface"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "find_parts",
        "operation": "search_and_identify",
        "participant_roles": ["compatible_component", "fastening_tool"],
        "operation_count": 1
      }
    ,
      {
        "id": "do_fastening",
        "operation": "apply_force",
        "participant_roles": ["fastening_tool", "compatible_component", "fastening_target"],
        "operation_count": 1
      }
    ,
      {
        "id": "put_back_tool",
        "operation": "place_object",
        "participant_roles": ["fastening_tool", "workbench_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "workbench surface",
          "visual_description": "Wooden tabletop surface of the desk."
        }
      ],
      "compatible_component": [
        {
          "label": "yellow items on tray",
          "visual_description": "Small yellow rectangular objects on a black tray on the table."
        }
      ],
      "fastening_tool": [
        {
          "label": "unknown",
          "visual_description": "Not clearly visible on the table; likely inside storage."
        }
      ],
      "workbench_surface": [
        {
          "label": "wooden tabletop",
          "visual_description": "The flat wooden surface of the desk."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "Left Under-Table Drawer",
        "visual_description": "Blue drawer with silver handle located under the left side of the desk.",
        "reason": "Closed storage structure likely containing small parts or tools."
      },
      {
        "id": "right_drawer",
        "label": "Right Under-Table Drawer",
        "visual_description": "Blue drawer with silver handle located under the right side of the desk.",
        "reason": "Closed storage structure likely containing small parts or tools."
      },
      {
        "id": "blue_cabinet",
        "label": "Blue Cabinet",
        "visual_description": "Tall blue storage unit standing behind the desk against the wall.",
        "reason": "Large closed storage structure likely containing larger tools or supplies."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "blue_cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
